import{_ as t,o as i,c as s,a2 as r}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse(`{"title":"L'Index des Dispositions Légales","description":"","frontmatter":{},"headers":[],"relativePath":"fr/92-法律条文索引.md","filePath":"fr/92-法律条文索引.md","lastUpdated":1789183869000}`),d={name:"fr/92-法律条文索引.md"};function o(a,e,l,n,u,c){return i(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="l-index-des-dispositions-legales" tabindex="-1">L&#39;Index des Dispositions Légales <a class="header-anchor" href="#l-index-des-dispositions-legales" aria-label="Permalink to &quot;L&#39;Index des Dispositions Légales&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>92</td></tr><tr><td>Module</td><td>Annexes et documents de référence</td></tr><tr><td>Mots clés</td><td>index juridique, Constitution Symbiotique, droit du travail, loi de protection des consommateurs, lois complémentaires</td></tr></tbody></table><h2 id="i-notes-sur-l-index" tabindex="-1">I. Notes sur l&#39;Index <a class="header-anchor" href="#i-notes-sur-l-index" aria-label="Permalink to &quot;I. Notes sur l&#39;Index&quot;">​</a></h2><p>Le présent index recense les principaux documents juridiques en vigueur dans la Civilisation Symbiotique de l&#39;Ancre et leurs dispositions fondamentales, classés par hiérarchie légale et par département. Le champ de l&#39;index couvre la Constitution Symbiotique, la Loi Symbiotique du Travail, la Loi de Protection des Consommateurs, ainsi que les cinq lois complémentaires sur l&#39;éducation, les soins médicaux, le logement, l&#39;environnement et les monopoles. Chaque entrée indique le nom de la loi, le numéro de la disposition et un résumé du contenu fondamental de la disposition. Le présent index est un outil de consultation ; pour le texte complet des dispositions légales et les interprétations judiciaires, se référer aux textes officiels des lois respectives.</p><h2 id="ii-la-constitution-symbiotique" tabindex="-1">II. La Constitution Symbiotique <a class="header-anchor" href="#ii-la-constitution-symbiotique" aria-label="Permalink to &quot;II. La Constitution Symbiotique&quot;">​</a></h2><p>La Constitution Symbiotique est la loi fondamentale de la Civilisation Symbiotique de l&#39;Ancre, possédant la plus haute force juridique, promulguée au moment de l&#39;établissement formel de la civilisation symbiotique.</p><table tabindex="0"><thead><tr><th>N° de disposition</th><th>Contenu fondamental</th></tr></thead><tbody><tr><td>Article 1</td><td>Établit l&#39;Univers Hengyuan (l&#39;Univers Originel Wanling Hengmao) comme domaine gouverné de la Civilisation Symbiotique de l&#39;Ancre ; le but fondamental de la civilisation symbiotique est de réaliser la symbiose des Dix Mille Races et l&#39;élévation de l&#39;univers</td></tr><tr><td>Article 2</td><td>Établit l&#39;anti-prédation comme position fondamentale de la civilisation, interdisant la culture prédatrice et la prédation des ressources sous toutes leurs formes</td></tr><tr><td>Article 3</td><td>Établit « rendre le droit de choisir le destin et l&#39;évolution à tous les êtres vivants » comme concept central de la civilisation</td></tr><tr><td>Article 4</td><td>Établit plus de travail, plus de gain ; la croissance autonome ; une voie pour chacun ; et la progression commune des Dix Mille Races comme politiques fondamentales de la civilisation</td></tr><tr><td>Article 5</td><td>Établit le système d&#39;ouverture gratuite des Trois Cents Systèmes de Culture de l&#39;Origine ; aucune organisation ni aucun individu ne peut monopoliser les droits de transmission des systèmes de culture</td></tr><tr><td>Article 6</td><td>Établit le Mécanisme de Contrat Lié à la Production comme système fondamental de distribution des ressources</td></tr><tr><td>Article 7</td><td>Établit la Stratégie d&#39;Activation de 20 % comme objectif national par étapes</td></tr><tr><td>Article 8</td><td>Établit le principe de la Réalité comme Fondement : le monde réel est le seul monde réel, et les configurations fictives n&#39;ont aucune force juridique</td></tr><tr><td>Article 9</td><td>Établit la Voie d&#39;Élévation en Quatre Étapes comme stratégie de développement à long terme de la civilisation</td></tr><tr><td>Article 10</td><td>Établit le principe d&#39;égalité des Dix Mille Races ; toutes les formes de vie sont égales devant la loi</td></tr><tr><td>Article 11</td><td>Établit le principe d&#39;évolution symbiotique ; l&#39;évolution individuelle ne doit pas se faire au détriment des droits d&#39;évolution d&#39;autres individus ou collectifs</td></tr><tr><td>Article 12</td><td>Établit le principe de plus de travail, plus de gain ; la distribution des ressources repose sur la contribution comme base fondamentale</td></tr><tr><td>Article 13</td><td>Établit le principe de croissance autonome ; le droit de choix autonome de l&#39;évolution de chaque vie est respecté</td></tr><tr><td>Article 14</td><td>Établit le principe d&#39;une voie pour chacun ; l&#39;État a l&#39;obligation de fournir à chaque vie une voie d&#39;évolution fondamentale et une garantie de ressources</td></tr><tr><td>Article 15</td><td>Établit le principe de durabilité ; tout développement doit tenir compte de la durabilité de l&#39;origine de l&#39;univers</td></tr><tr><td>Articles 16–25</td><td>Disposent des droits fondamentaux de tous les êtres vivants : le droit de choisir l&#39;évolution, le droit d&#39;obtenir des ressources de culture, le droit à une protection égale, le droit de participer à la symbiose, le droit à la préservation culturelle, le droit au secours et au recours, le droit à la liberté de la personne, le droit à la dignité de la personne, le droit à la liberté de croyance et le droit à la liberté d&#39;expression</td></tr><tr><td>Articles 26–31</td><td>Disposent des obligations fondamentales de tous les êtres vivants : l&#39;obligation de respecter la loi, de maintenir l&#39;ordre symbiotique, de contribuer par le travail, de protéger l&#39;environnement, de respecter les droits d&#39;autrui et de guider les cultivateurs débutants</td></tr><tr><td>Article 32</td><td>Établit l&#39;Assemblée Délibérante de l&#39;Ancre comme organe suprême du pouvoir, composée de représentants des Dix Mille Races en proportion</td></tr><tr><td>Article 33</td><td>Établit le Comité Exécutif Symbiotique comme organe administratif suprême</td></tr><tr><td>Article 34</td><td>Établit le Tribunal Symbiotique comme organe judiciaire suprême, exerçant indépendamment le pouvoir judiciaire</td></tr><tr><td>Article 35</td><td>Établit le Comité de Supervision de l&#39;Ancre comme organe de supervision indépendant</td></tr><tr><td>Article 36</td><td>Dispose de la procédure législative : un projet de loi est adopté à la majorité de plus de la moitié de l&#39;Assemblée Délibérante de l&#39;Ancre</td></tr><tr><td>Article 37</td><td>Dispose de la procédure de révision constitutionnelle : elle doit être adoptée à la majorité de plus des deux tiers de l&#39;Assemblée Délibérante de l&#39;Ancre et approuvée par plus de la moitié de la population par référendum</td></tr><tr><td>Article 38</td><td>Établit le système de contrôle de constitutionnalité ; le Tribunal Symbiotique a le pouvoir de déclarer nulles les lois qui violent la Constitution</td></tr><tr><td>Article 39</td><td>Établit le système de contentieux constitutionnel ; tous les êtres vivants peuvent intenter directement une action en justice conformément à la Constitution</td></tr><tr><td>Article 40</td><td>Dispose du système d&#39;autonomie locale ; chaque domaine stellaire et chaque plan mettent en œuvre l&#39;autonomie dans le cadre de la Constitution</td></tr><tr><td>Article 41</td><td>Établit le système républicain des Dix Mille Races ; toutes les races sont égales dans la civilisation symbiotique et mettent en œuvre l&#39;autonomie régionale</td></tr><tr><td>Article 42</td><td>Dispose du système économique de la civilisation symbiotique : fondé sur les contrats liés à la production, avec le développement conjoint de multiples formes de propriété</td></tr><tr><td>Article 43</td><td>Dispose du système de propriété d&#39;État et de distribution équitable des ressources de culture</td></tr><tr><td>Article 44</td><td>Établit le système d&#39;équité éducative, garantissant le droit égal à l&#39;éducation de chaque vie</td></tr><tr><td>Article 45</td><td>Établit le système de sécurité médicale universelle</td></tr><tr><td>Article 46</td><td>Établit le système de sécurité du logement, garantissant le droit fondamental au logement de chaque vie</td></tr><tr><td>Article 47</td><td>Dispose des principes fondamentaux de l&#39;interaction transplans ; la circulation transplans non autorisée est interdite</td></tr><tr><td>Article 48</td><td>Dispose que les produits légitimes des activités archéologiques se limitent aux connaissances et informations abstraites ; le retour de matière et d&#39;énergie est interdit</td></tr><tr><td>Article 49</td><td>Dispose des principes fondamentaux de la régression temporelle ; le principe d&#39;observer d&#39;abord puis d&#39;intervenir dans les limites doit être suivi</td></tr><tr><td>Article 50</td><td>Dispose que le pouvoir d&#39;interprétation de la Constitution appartient au Tribunal Symbiotique, et que le pouvoir de révision de la Constitution appartient à l&#39;Assemblée Délibérante de l&#39;Ancre</td></tr></tbody></table><h2 id="iii-la-loi-symbiotique-du-travail" tabindex="-1">III. La Loi Symbiotique du Travail <a class="header-anchor" href="#iii-la-loi-symbiotique-du-travail" aria-label="Permalink to &quot;III. La Loi Symbiotique du Travail&quot;">​</a></h2><p>La Loi Symbiotique du Travail est la loi fondamentale régissant les relations de travail et protégeant les droits et intérêts des travailleurs, promulguée sur la base législative de l&#39;article 42 de la Constitution Symbiotique.</p><table tabindex="0"><thead><tr><th>N° de disposition</th><th>Contenu fondamental</th></tr></thead><tbody><tr><td>Article 1</td><td>Objet législatif : réguler les relations de travail, protéger les droits et intérêts légitimes des travailleurs et construire des relations de travail harmonieuses et symbiotiques</td></tr><tr><td>Article 2</td><td>Champ d&#39;application : toutes les relations de travail au sein de l&#39;Univers Hengyuan, y compris le travail matériel, le travail de culture et le travail créatif</td></tr><tr><td>Article 3</td><td>Établit le principe d&#39;égalité d&#39;emploi des travailleurs ; la discrimination à l&#39;emploi fondée sur la race, le sexe, le niveau de culture ou l&#39;origine est interdite</td></tr><tr><td>Article 4</td><td>Établit le principe de libre choix de l&#39;emploi ; le travail forcé et l&#39;esclavage sont interdits</td></tr><tr><td>Article 5</td><td>Dispose du système de contrat de travail ; un contrat de travail écrit doit être conclu lors de l&#39;établissement d&#39;une relation de travail</td></tr><tr><td>Article 6</td><td>Dispose des clauses obligatoires du contrat de travail : durée du contrat, contenu du travail, rémunération du travail, temps de travail, protection du travail et assurance sociale</td></tr><tr><td>Article 7</td><td>Établit la journée de travail de huit heures et le système de temps de travail de quarante-quatre heures au maximum par semaine</td></tr><tr><td>Article 8</td><td>Dispose des restrictions d&#39;heures supplémentaires : pas plus d&#39;une heure par jour, trois heures dans des circonstances particulières, et pas plus de trente-six heures par mois</td></tr><tr><td>Article 9</td><td>Dispose des normes de rémunération des heures supplémentaires : 1,5 fois le salaire pour les heures supplémentaires en semaine, 2 fois le salaire pour les heures supplémentaires les jours de repos et 3 fois le salaire pour les heures supplémentaires les jours fériés légaux</td></tr><tr><td>Article 10</td><td>Établit le système de garantie du salaire minimum ; le niveau du salaire minimum est fixé par chaque domaine stellaire selon les conditions locales</td></tr><tr><td>Article 11</td><td>Dispose du système de paiement du salaire : le salaire doit être payé mensuellement au travailleur personnellement sous forme monétaire, sans retenue ni retard injustifié</td></tr><tr><td>Article 12</td><td>Établit le principe de distribution de plus de travail, plus de gain ; un système de distribution avec la distribution selon le travail comme corps principal et la coexistence de multiples méthodes de distribution est mis en œuvre</td></tr><tr><td>Article 13</td><td>Dispose du système de sécurité et de santé au travail ; les employeurs doivent fournir aux travailleurs des conditions de sécurité et de santé au travail conformes aux normes</td></tr><tr><td>Article 14</td><td>Dispose de la protection des groupes spéciaux : une protection spéciale du travail est mise en œuvre pour les travailleurs mineurs, les travailleuses, les travailleurs handicapés et les travailleurs de faible niveau de culture</td></tr><tr><td>Article 15</td><td>Établit le système de formation professionnelle ; les employeurs ont l&#39;obligation de dispenser une formation professionnelle aux travailleurs</td></tr><tr><td>Article 16</td><td>Dispose des droits du travail des cultivateurs : le travail de culture est également protégé par la présente loi, et l&#39;attribution des résultats de culture est convenue par contrat</td></tr><tr><td>Article 17</td><td>Établit le système d&#39;assurance sociale des travailleurs : assurance vieillesse, assurance maladie, assurance chômage, assurance accidents du travail et assurance maternité</td></tr><tr><td>Article 18</td><td>Dispose du système de prestations sociales des travailleurs : les employeurs doivent fournir aux travailleurs les prestations nécessaires</td></tr><tr><td>Article 19</td><td>Établit le système de traitement des conflits du travail : un mécanisme de traitement à quatre niveaux de conciliation, médiation, arbitrage et contentieux</td></tr><tr><td>Article 20</td><td>Dispose du système syndical ; les travailleurs ont le droit d&#39;organiser et de rejoindre des syndicats conformément à la loi pour protéger leurs droits et intérêts légitimes</td></tr><tr><td>Article 21</td><td>Dispose du système de convention collective ; les syndicats représentent les travailleurs dans la conclusion de conventions collectives avec les employeurs</td></tr><tr><td>Article 22</td><td>Dispose que le règlement intérieur d&#39;un employeur doit être discuté par le congrès des travailleurs ou l&#39;ensemble des travailleurs</td></tr><tr><td>Article 23</td><td>Dispose des conditions et de la procédure de résiliation des contrats de travail</td></tr><tr><td>Article 24</td><td>Dispose du système d&#39;indemnité économique ; les employeurs doivent verser une indemnité économique lors de la résiliation légale d&#39;un contrat de travail</td></tr><tr><td>Article 25</td><td>Dispose du système de dommages-intérêts pour résiliation illégale du contrat de travail</td></tr><tr><td>Article 26</td><td>Établit le système de gestion du travail intérimaire, régulant l&#39;emploi par travail intérimaire</td></tr><tr><td>Article 27</td><td>Dispose des règles spéciales du travail à temps partiel</td></tr><tr><td>Article 28</td><td>Dispose du système de contrôle et d&#39;inspection ; les services administratifs du travail contrôlent et inspectent le respect des lois et règlements du travail par les employeurs conformément à la loi</td></tr><tr><td>Article 29</td><td>Dispose de la responsabilité légale : les employeurs qui violent la présente loi engagent leur responsabilité administrative, civile et pénale conformément à la loi</td></tr><tr><td>Article 30</td><td>Dispose de la date d&#39;entrée en vigueur et du pouvoir d&#39;interprétation de la présente loi</td></tr></tbody></table><h2 id="iv-la-loi-de-protection-des-consommateurs" tabindex="-1">IV. La Loi de Protection des Consommateurs <a class="header-anchor" href="#iv-la-loi-de-protection-des-consommateurs" aria-label="Permalink to &quot;IV. La Loi de Protection des Consommateurs&quot;">​</a></h2><p>La Loi de Protection des Consommateurs est la loi fondamentale protégeant les droits et intérêts légitimes des consommateurs et régulant la conduite des opérateurs économiques.</p><table tabindex="0"><thead><tr><th>N° de disposition</th><th>Contenu fondamental</th></tr></thead><tbody><tr><td>Article 1</td><td>Objet législatif : protéger les droits et intérêts légitimes des consommateurs, maintenir l&#39;ordre économique et social et promouvoir le développement sain de l&#39;économie de marché symbiotique</td></tr><tr><td>Article 2</td><td>Champ d&#39;application : la protection des droits et intérêts des consommateurs au sein de l&#39;Univers Hengyuan lors de l&#39;achat et de l&#39;utilisation de marchandises ou de la réception de services pour les besoins de la vie quotidienne</td></tr><tr><td>Article 3</td><td>Établit les principes fondamentaux des transactions entre opérateurs et consommateurs : volontariat, égalité, équité et bonne foi</td></tr><tr><td>Article 4</td><td>Établit le principe de protection par l&#39;État des droits et intérêts légitimes des consommateurs ; l&#39;État prend des mesures pour garantir que les consommateurs exercent leurs droits conformément à la loi</td></tr><tr><td>Article 5</td><td>Dispose des neuf droits fondamentaux des consommateurs : le droit à la sécurité, le droit à l&#39;information, le droit au libre choix, le droit à un commerce équitable, le droit à réparation, le droit d&#39;association, le droit au savoir, le droit au respect et le droit de contrôle</td></tr><tr><td>Article 6</td><td>Dispose du droit à la sécurité du consommateur : les consommateurs jouissent du droit à ce que leur sécurité personnelle et patrimoniale ne soit pas compromise lors de l&#39;achat et de l&#39;utilisation de marchandises et de la réception de services</td></tr><tr><td>Article 7</td><td>Dispose du droit à l&#39;information du consommateur : les consommateurs jouissent du droit de connaître la situation réelle des marchandises qu&#39;ils achètent ou utilisent et des services qu&#39;ils reçoivent</td></tr><tr><td>Article 8</td><td>Dispose du droit au libre choix du consommateur : les consommateurs jouissent du droit de choisir librement les marchandises ou les services</td></tr><tr><td>Article 9</td><td>Dispose du droit au commerce équitable du consommateur : les consommateurs jouissent du droit au commerce équitable et ont le droit de refuser les transactions coercitives</td></tr><tr><td>Article 10</td><td>Dispose du droit à réparation du consommateur : les consommateurs qui subissent des dommages personnels ou patrimoniaux du fait de l&#39;achat et de l&#39;utilisation de marchandises ou de la réception de services jouissent du droit d&#39;obtenir réparation conformément à la loi</td></tr><tr><td>Article 11</td><td>Dispose des obligations fondamentales des opérateurs : accomplir les obligations légales et convenues, accepter le contrôle, garantir la sécurité, fournir des informations véridiques, délivrer des reçus, garantir la qualité, accomplir les trois garanties, s&#39;abstenir de commerce déloyal et s&#39;abstenir de porter atteinte à la dignité de la personne</td></tr><tr><td>Article 12</td><td>Dispose de l&#39;obligation de garantie de sécurité des opérateurs : les opérateurs doivent garantir que les marchandises ou services qu&#39;ils fournissent répondent aux exigences de protection de la sécurité personnelle et patrimoniale</td></tr><tr><td>Article 13</td><td>Dispose de l&#39;obligation de divulgation d&#39;informations des opérateurs : les opérateurs doivent fournir aux consommateurs des informations véridiques sur les marchandises ou services, sans publicité mensongère ou trompeuse</td></tr><tr><td>Article 14</td><td>Dispose des normes spéciales pour les produits et services de culture : les opérateurs de méthodes de culture, d&#39;instruments de culture et de produits énergétiques doivent posséder des qualifications spéciales, et les produits doivent passer une certification de sécurité</td></tr><tr><td>Article 15</td><td>Dispose de la régulation des clauses types : les opérateurs ne peuvent pas utiliser des clauses types pour exclure ou limiter les droits des consommateurs, ni pour atténuer ou exonérer la responsabilité de l&#39;opérateur</td></tr><tr><td>Article 16</td><td>Dispose du système de retour sans motif de sept jours : les consommateurs qui achètent des marchandises par des moyens à distance tels que le réseau ont le droit de retourner les marchandises dans les sept jours à compter de la date de réception</td></tr><tr><td>Article 17</td><td>Dispose du système des trois garanties : si les marchandises ou services fournis par les opérateurs ne répondent pas aux exigences de qualité, les consommateurs peuvent demander la réparation, le remplacement ou le retour conformément aux règlements nationaux</td></tr><tr><td>Article 18</td><td>Dispose du système de dommages-intérêts punitifs : si les opérateurs fournissent des marchandises ou services en commettant une fraude, ils doivent, conformément aux exigences des consommateurs, augmenter l&#39;indemnisation de leurs pertes, le montant de l&#39;indemnisation supplémentaire étant de trois fois le prix des marchandises achetées ou le coût des services reçus par le consommateur</td></tr><tr><td>Article 19</td><td>Dispose des organisations de consommateurs : les associations de consommateurs et autres organisations de consommateurs sont des organisations sociales légalement établies pour exercer un contrôle social sur les marchandises et services et pour protéger les droits et intérêts légitimes des consommateurs</td></tr><tr><td>Article 20</td><td>Dispose des voies de résolution des litiges de consommation : négociation et règlement avec l&#39;opérateur, demande de médiation à l&#39;association de consommateurs, recours auprès des services administratifs compétents, saisine de l&#39;arbitrage et action en justice devant le tribunal</td></tr><tr><td>Article 21</td><td>Dispose du renversement de la charge de la preuve dans les litiges : pour les marchandises durables ou les services tels que la décoration, si les consommateurs découvrent des défauts dans les six mois suivant la réception, la charge de la preuve incombe à l&#39;opérateur</td></tr><tr><td>Article 22</td><td>Dispose de la responsabilité administrative et pénale des opérateurs</td></tr><tr><td>Article 23</td><td>Dispose de la date d&#39;entrée en vigueur et du pouvoir d&#39;interprétation de la présente loi</td></tr></tbody></table><h2 id="v-les-cinq-lois-complementaires" tabindex="-1">V. Les Cinq Lois Complémentaires <a class="header-anchor" href="#v-les-cinq-lois-complementaires" aria-label="Permalink to &quot;V. Les Cinq Lois Complémentaires&quot;">​</a></h2><h3 id="_5-1-la-loi-de-garantie-de-l-education" tabindex="-1">5.1 La Loi de Garantie de l&#39;Éducation <a class="header-anchor" href="#_5-1-la-loi-de-garantie-de-l-education" aria-label="Permalink to &quot;5.1 La Loi de Garantie de l&#39;Éducation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>N° de disposition</th><th>Contenu fondamental</th></tr></thead><tbody><tr><td>Article 1</td><td>Objet législatif : garantir le droit égal à l&#39;éducation de tous les êtres vivants, construire un système éducatif symbiotique et promouvoir le développement commun des cultures des Dix Mille Races</td></tr><tr><td>Articles 2–5</td><td>Établissent le principe d&#39;équité éducative, le principe de gratuité de l&#39;éducation (au stade de l&#39;éducation fondamentale), le principe de diversité éducative et le principe d&#39;innovation éducative</td></tr><tr><td>Articles 6–10</td><td>Disposent de l&#39;architecture du système d&#39;éducation préscolaire, d&#39;éducation obligatoire, d&#39;éducation secondaire supérieure, d&#39;éducation supérieure et d&#39;éducation de culture</td></tr><tr><td>Articles 11–15</td><td>Disposent des systèmes spéciaux de l&#39;éducation de culture : les normes pédagogiques des Trois Cents Systèmes, le système de mentorat et le système d&#39;allocation des ressources de culture</td></tr><tr><td>Articles 16–20</td><td>Disposent des droits et obligations des enseignants, du système de qualification des enseignants et de la garantie du traitement des enseignants</td></tr><tr><td>Articles 21–25</td><td>Disposent de la garantie des investissements éducatifs, de la construction d&#39;installations éducatives, de l&#39;informatisation de l&#39;éducation, de l&#39;éducation spéciale et de l&#39;éducation interraciale</td></tr><tr><td>Articles 26–30</td><td>Disposent du système d&#39;évaluation de l&#39;éducation, du système de contrôle de l&#39;éducation, de la responsabilité légale et des dispositions complémentaires</td></tr></tbody></table><h3 id="_5-2-la-loi-de-securite-medicale" tabindex="-1">5.2 La Loi de Sécurité Médicale <a class="header-anchor" href="#_5-2-la-loi-de-securite-medicale" aria-label="Permalink to &quot;5.2 La Loi de Sécurité Médicale&quot;">​</a></h3><table tabindex="0"><thead><tr><th>N° de disposition</th><th>Contenu fondamental</th></tr></thead><tbody><tr><td>Article 1</td><td>Objet législatif : établir un système de sécurité médicale universelle, garantir le droit à la santé de tous les êtres vivants et améliorer le niveau de santé global des Dix Mille Races</td></tr><tr><td>Articles 2–5</td><td>Établissent le principe d&#39;assurance maladie universelle, le principe de gratuité des soins médicaux fondamentaux, le principe d&#39;intégration de la médecine chinoise et occidentale et le principe d&#39;incorporation de la médecine de culture</td></tr><tr><td>Articles 6–10</td><td>Disposent du système d&#39;assurance maladie à plusieurs niveaux : assurance maladie fondamentale, assurance contre les maladies graves, aide médicale et assurance maladie commerciale</td></tr><tr><td>Articles 11–15</td><td>Disposent de la gestion des établissements médicaux, du système du personnel soignant, de la qualité et de la sécurité médicales et des normes spéciales de la médecine de culture</td></tr><tr><td>Articles 16–20</td><td>Disposent de la gestion des médicaments, de la gestion des dispositifs médicaux, de la gestion des produits médicaux énergétiques et du système des médicaments essentiels</td></tr><tr><td>Articles 21–25</td><td>Disposent du système de santé publique, de la prévention et du contrôle des maladies, de l&#39;éducation sanitaire, des soins médicaux interraciaux et de la sécurité médicale des groupes spéciaux</td></tr><tr><td>Articles 26–30</td><td>Disposent du traitement des litiges médicaux, du contrôle médical, de la responsabilité légale et des dispositions complémentaires</td></tr></tbody></table><h3 id="_5-3-la-loi-de-securite-du-logement" tabindex="-1">5.3 La Loi de Sécurité du Logement <a class="header-anchor" href="#_5-3-la-loi-de-securite-du-logement" aria-label="Permalink to &quot;5.3 La Loi de Sécurité du Logement&quot;">​</a></h3><table tabindex="0"><thead><tr><th>N° de disposition</th><th>Contenu fondamental</th></tr></thead><tbody><tr><td>Article 1</td><td>Objet législatif : garantir le droit fondamental au logement de tous les êtres vivants, construire un système de sécurité du logement à plusieurs niveaux et réaliser le logement pour tous</td></tr><tr><td>Articles 2–5</td><td>Établissent le principe de garantie du droit au logement, le principe d&#39;équité du logement, le principe de location et d&#39;achat conjoints et le principe de logement durable</td></tr><tr><td>Articles 6–10</td><td>Disposent du système d&#39;offre de logement : logements locatifs publics, logements locatifs aidés, logements en propriété partagée et logements commerciaux</td></tr><tr><td>Articles 11–15</td><td>Disposent du système de fonds de logement, du système de subventions au logement, des politiques de soutien au premier logement et des politiques spéciales de logement pour les cultivateurs</td></tr><tr><td>Articles 16–20</td><td>Disposent des normes de construction du logement, de l&#39;application de la technologie spatiale dans le logement, des bâtiments verts et des logements adaptés aux personnes âgées et sans obstacles</td></tr><tr><td>Articles 21–25</td><td>Disposent de la régulation du marché immobilier, des normes du marché locatif, de la gestion des services immobiliers et de la garantie d&#39;entretien du logement</td></tr><tr><td>Articles 26–30</td><td>Disposent du contrôle de la sécurité du logement, de la responsabilité légale et des dispositions complémentaires</td></tr></tbody></table><h3 id="_5-4-la-loi-de-protection-de-l-environnement" tabindex="-1">5.4 La Loi de Protection de l&#39;Environnement <a class="header-anchor" href="#_5-4-la-loi-de-protection-de-l-environnement" aria-label="Permalink to &quot;5.4 La Loi de Protection de l&#39;Environnement&quot;">​</a></h3><table tabindex="0"><thead><tr><th>N° de disposition</th><th>Contenu fondamental</th></tr></thead><tbody><tr><td>Article 1</td><td>Objet législatif : protéger et améliorer l&#39;environnement, prévenir et contrôler la pollution et autres nuisances publiques, garantir la santé publique, promouvoir la construction de la civilisation écologique cosmique et faire progresser le développement durable</td></tr><tr><td>Articles 2–5</td><td>Établissent le principe de priorité à la protection, le principe de prévention primaire, le principe de traitement global, le principe de participation publique et le principe de responsabilité pour les dommages</td></tr><tr><td>Articles 6–10</td><td>Disposent du système de contrôle et de gestion de l&#39;environnement, du système de normes environnementales, du système d&#39;évaluation de l&#39;impact environnemental, du système de surveillance environnementale et de la gestion environnementale transplans</td></tr><tr><td>Articles 11–15</td><td>Disposent de la prévention et du contrôle de la pollution atmosphérique, de la pollution de l&#39;eau, de la pollution des sols, de la pollution énergétique et de la pollution des lois</td></tr><tr><td>Articles 16–20</td><td>Disposent du traitement des déchets solides, de la prévention et du contrôle de la pollution sonore, de la prévention et du contrôle de la pollution radioactive, de la protection écologique et de la protection de la biodiversité</td></tr><tr><td>Articles 21–25</td><td>Disposent du contrôle de l&#39;impact environnemental des activités de culture, de la protection écologique de l&#39;extraction énergétique et des exigences environnementales de l&#39;archéologie transplans</td></tr><tr><td>Articles 26–30</td><td>Disposent de la divulgation d&#39;informations et de la participation publique, de l&#39;action en justice d&#39;intérêt public environnementale, de la responsabilité légale et des dispositions complémentaires</td></tr></tbody></table><h3 id="_5-5-la-loi-antimonopole" tabindex="-1">5.5 La Loi Antimonopole <a class="header-anchor" href="#_5-5-la-loi-antimonopole" aria-label="Permalink to &quot;5.5 La Loi Antimonopole&quot;">​</a></h3><table tabindex="0"><thead><tr><th>N° de disposition</th><th>Contenu fondamental</th></tr></thead><tbody><tr><td>Article 1</td><td>Objet législatif : prévenir et faire cesser les comportements monopolistiques, protéger la concurrence loyale du marché, améliorer l&#39;efficacité du fonctionnement économique, sauvegarder les intérêts des consommateurs et l&#39;intérêt public de la société et promouvoir le développement sain de l&#39;économie de marché symbiotique</td></tr><tr><td>Articles 2–5</td><td>Établissent la position fondamentale de la politique de concurrence, le système d&#39;examen de la concurrence loyale, l&#39;interdiction des accords monopolistiques, l&#39;interdiction de l&#39;abus de position dominante sur le marché et le contrôle de la concentration des entreprises</td></tr><tr><td>Articles 6–10</td><td>Disposent de la détermination et de l&#39;exemption des accords monopolistiques, des accords monopolistiques horizontaux, des accords monopolistiques verticaux et des comportements monopolistiques des associations professionnelles</td></tr><tr><td>Articles 11–15</td><td>Disposent de la détermination de la position dominante sur le marché, des types de comportements constitutifs d&#39;abus de position dominante et de l&#39;interdiction des prix d&#39;éviction</td></tr><tr><td>Articles 16–20</td><td>Disposent des normes de déclaration de la concentration des entreprises, de la procédure d&#39;examen, des conditions restrictives supplémentaires et des décisions interdisant la concentration</td></tr><tr><td>Articles 21–25</td><td>Disposent de l&#39;interdiction spéciale des monopoles dans les systèmes de culture : interdiction de monopoliser les méthodes de culture, interdiction de monopoliser les ressources de culture et interdiction de monopoliser les réseaux de mentors</td></tr><tr><td>Articles 26–30</td><td>Disposent de l&#39;autorité d&#39;application de la loi antimonopole, de la procédure d&#39;enquête, de la responsabilité légale, du système de clémence et des dispositions complémentaires</td></tr></tbody></table><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>L&#39;index des dispositions légales est la carte de consultation du système de l&#39;État de droit de la Civilisation Symbiotique de l&#39;Ancre. De la Constitution Symbiotique comme loi fondamentale, aux lois du travail et de protection des consommateurs régissant le bien-être du peuple, puis aux cinq lois complémentaires, ils constituent ensemble un système juridique complet « avec la Constitution comme commandant, les lois fondamentales comme colonne vertébrale et les lois complémentaires comme soutien ». Ce système garantit que toutes les activités de la civilisation symbiotique fonctionnent sur la voie de l&#39;État de droit, fournissant une garantie institutionnelle solide pour la progression commune des Dix Mille Races.</p><h2 id="documents-connexes" tabindex="-1">Documents Connexes <a class="header-anchor" href="#documents-connexes" aria-label="Permalink to &quot;Documents Connexes&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Constitution Symbiotique : Principes Généraux)</li><li>41-共生劳动法 (Loi Symbiotique du Travail)</li><li>48-司法体系与裁决机制 (Système Judiciaire et Mécanisme d&#39;Adjudication)</li></ul>',28)])])}const v=t(d,[["render",o]]);export{p as __pageData,v as default};
